import pandas as pd, numpy as np
for i in [1,2,3,5,11,12,13]:
    df = pd.read_csv(eval(f"experiment_{i}_csv"))
    cols = df.columns.tolist()
    tp = df["JobThroughput"].mean() if "JobThroughput" in cols else None
    print(f"exp{i}: n={len(df)} cols={cols}")
    if tp is not None:
        print(f"   JobThroughput mean={tp:.2f} sd={df['JobThroughput'].std():.2f}")
    # print any do_ columns unique values
    for c in cols:
        if c.startswith("do_"):
            print(f"   {c} unique={df[c].unique()}")
